from lib import *
S = SS('p6')
steps = [
    step("requests 默认发的 Accept-Encoding 取决于本机装了什么库:没装 brotli 时是 gzip, deflate, zstd;装了 brotli(这里是 1.2.0)后变成 gzip, deflate, br, zstd。zstd 不用另装,Python 3.14 标准库自带 compression.zstd。也就是说,同一份爬虫代码换一台机器,发给服务器的请求头可能就不一样。", t=tl(S(1)), done=lidx(S(1), '装了 brotli:'), mark=lidx(S(1), '没装 brotli:'), kv=KV([['没装 brotli', 'gzip, deflate, zstd'], ['装了 brotli', 'gzip, deflate, br, zstd'], ['zstd', 'Python 3.14 标准库自带']], ['装了 brotli'])),
    step("同一个 291470 字节的重复 HTML(3000 行商品)用不同方式传输,线上字节数:identity 291470(100%)、gzip 21308(7.3%)、deflate 21296(7.3%)、zstd 14369(4.9%)、br 9196(3.2%);客户端自动解压后长度都是 291470,内容与原文一致。注意比例只对这份数据和我用的压缩参数(gzip 6、zstd 默认、br quality 5)成立。", t=tl(S(2)), done=lidx(S(2), 'br    ', 'zstd  '), mark=lidx(S(2), 'identity'), b=bars([['identity', 291470, '291470'], ['gzip', 21308, '21308'], ['deflate', 21296, '21296'], ['zstd', 14369, '14369'], ['br', 9196, '9196']], 291470, mark=[0], done=[3, 4]), kv=KV([['gzip', '7.3%'], ['zstd', '4.9%'], ['br', '3.2%(quality 5)']], ['br'])),
    step("不可压缩的数据(291470 字节随机字节,像已经压缩过的图片、视频)压缩没有收益,反而略微变大:gzip 291578、deflate 291566、zstd 291488、br 291475,都在 100.0% 附近。爬虫抓图片、压缩包时,这类响应的 Content-Encoding 不会帮你省流量。", t=tl(S(3)), done=lidx(S(3), 'identity'), mark=lidx(S(3), 'gzip  ', 'deflate', 'zstd', 'br  '), b=bars([['identity', 291470, '291470'], ['gzip', 291578, '291578'], ['zstd', 291488, '291488']], 291600, done=[0], mark=[1]), kv=KV([['随机数据', '压缩后 ≥ 原始大小'], ['最差', 'gzip 多 108 字节'], ['适用', '文本类内容才有收益']], ['随机数据'])),
    step("服务器无视 Accept-Encoding、硬发 Content-Encoding: br 的响应(9196 字节):客户端装了 brotli,r.content 是解压后的 291470 字节、与原文一致;没装 brotli 的客户端不报错,r.content 却是原样的 9196 字节压缩数据,与原文不一致——拿它去解析会得到乱码,而你看不到任何异常。", t=tl(S(4)), done=lidx(S(4), '装了 brotli:'), mark=lidx(S(4), '没装 brotli:'), b=bars([['没装 brotli 的 r.content', 9196, '9196'], ['装了 brotli 的 r.content', 291470, '291470']], 291470, mark=[0], done=[1]), kv=KV([['没装 brotli', '不报错,拿到压缩的原始字节'], ['装了 brotli', '正常解压'], ['风险', '解析阶段才发现乱码']], ['风险'])),
    step("压缩炸弹:线上只传 65250 字节(gzip),解压后是 64 MiB 的零。普通 requests.get 把全部解压进内存:r.content 67108864 字节,进程峰值内存 180 MiB(空进程加载 requests 后约 34 MiB),耗时 49 ms;stream=True 读满 1 MiB 就停,只读到 1048576 字节、2 ms、峰值内存 34 MiB。对不可信的页面,应限制读取量,而不是无条件 r.content。", t=tl(S(5)), done=lidx(S(5), 'stream + 读满'), mark=lidx(S(5), '普通 get', '线上传输'), b=bars([['线上字节', 65250, '65250'], ['普通 get 峰值内存 MiB', 180, '180'], ['stream 峰值内存 MiB', 34, '34']], 200, mark=[1], done=[2]), kv=KV([['线上', '65250 字节'], ['普通 get', '解压成 64 MiB,峰值内存 180 MiB'], ['stream 读 1 MiB', '峰值内存 34 MiB']], ['普通 get'])),
]
A = mkartp('p6', 6, '爬虫,requests,gzip,brotli,zstd,Content-Encoding,压缩炸弹,Python,真实验证,动画演示',
    '实测爬虫里的响应压缩:requests 默认的 Accept-Encoding 取决于本机是否装了 brotli(gzip, deflate, zstd 变成 gzip, deflate, br, zstd);同一页面 gzip 7.3%、zstd 4.9%、br 3.2%;随机数据压缩无收益;服务器硬发 br 而客户端没装库时 r.content 是未解压的乱码;65250 字节的 gzip 解压成 64 MiB。',
    'Accept-Encoding 看起来是个“自动的事”,但它决定了你从服务器拿到什么、省多少流量、遇到压缩炸弹时会不会把内存撑爆。这篇在本机用 gzip、deflate、zstd、br 各传一遍同一个页面,再试试没装库的客户端和一个 64 MiB 的压缩炸弹。',
    [('3.2%', 'br 传输同一个 HTML 页面的字节数占原始大小的比例(gzip 7.3%,zstd 4.9%)'), ('9196', '没装 brotli 的客户端拿到的 r.content 字节数——还是压缩数据,不报错'), ('180 MiB', '65250 字节的 gzip 响应用普通 get 解压后的进程峰值内存(stream 读 1 MiB 仅 34 MiB)')],
    [('Accept-Encoding 取决于装了什么', '<p>requests 通过 urllib3 声明自己能解哪些压缩:没装 brotli 时是 <code>gzip, deflate, zstd</code>,装了 brotli 后多出 <code>br</code>。zstd 来自 Python 3.14 标准库的 <code>compression.zstd</code>。因此换一台机器、装一个依赖,爬虫发给服务器的请求头就变了,这对排查“为什么这台机器上拿到的页面不一样”很重要。</p>'),
     ('不同压缩方式的体积', '<p>对 29 万字节的重复 HTML,gzip 和 deflate 都压到约 7.3%,zstd 4.9%,br 3.2%。这些数字依赖我选的压缩参数(gzip 6、zstd 默认、br quality 5)和这份高度重复的数据,不要当成通用比例。服务端实际用什么级别,取决于它自己的配置。</p>'),
     ('已压缩的内容不会再变小', '<p>随机字节(也近似已经压缩过的图片、视频)用任何方式压缩都不会变小,反而多出几十到一百多字节的头尾。对文本页面启用压缩有价值,对图片下载没有。</p>'),
     ('客户端没装解压库', '<p>服务器本不该发客户端没声明的编码,但如果发了,没装 brotli 的客户端不会抛异常,<code>r.content</code> 是原样的压缩字节(9196 字节),和原文不一致。如果你的解析代码直接处理这些字节,得到的只是乱码。检查 <code>Content-Encoding</code> 与实际内容长度是否匹配,可以尽早发现。</p>'),
     ('压缩炸弹', '<p>一个 65250 字节的 gzip 响应能解压成 64 MiB。普通 <code>requests.get</code> 把它全部放进内存,进程峰值 180 MiB;<code>stream=True</code> 读到上限就停,峰值只有 34 MiB。对不可信的站点,把读取量限制在合理范围内(这里只演示了按解压后的字节数截断,没有测别的防护方式)。</p>')],
    steps,
    [ENV_P + '。brotli 1.2.0 用 pip 装进实验专用的临时目录,客户端分别在装了和没装的环境里运行(用 PYTHONPATH 控制);zstd 用 Python 3.14 标准库 compression.zstd;服务器按路径强制返回指定编码;“线上字节”用 stream=True 加 r.raw.read(decode_content=False) 读取;内存是进程的 ru_maxrss;gzip 压缩级别 6、br quality 5、zstd 默认级别',
     '没有验证:真实站点(nginx、CDN)按 Accept-Encoding 协商压缩的行为;不同压缩级别与不同内容类型下的比例;aiohttp 的解压行为;Transfer-Encoding 与 Content-Encoding 叠加的情形;限制解压后大小的其它办法(如 urllib3 的相关参数,没有试);brotli 的流式解压内存占用'],
    '响应压缩')
